package org.sleepwell.app;
import android.app.job.*;import android.content.*;import android.os.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.util.function.*;
/** Provider work is serial; a bounded metadata-only worker can durably turn consent Off. */
final class AutoCloudBackups {
 static final int JOB=7416;
 interface Factory {AutoCloudBackupStore open(Context c);}
 static final Factory PRODUCTION=AutoCloudBackupStore::new;static Factory factory=PRODUCTION;
 interface Environments {AutoCloudBackupEngine.Environment create(Context c,Records.Factory records);}
 static final Environments PRODUCTION_ENVIRONMENT=AndroidEnvironment::new;static Environments environments=PRODUCTION_ENVIRONMENT;
 static final ExecutorService io=Executors.newSingleThreadExecutor(r->new Thread(r,"automatic-metadata-backup"));
 private static final ExecutorService control=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(2),r->new Thread(r,"automatic-backup-consent"),new ThreadPoolExecutor.AbortPolicy());
 private static final AtomicBoolean offPending=new AtomicBoolean();
 private static final AtomicLong generation=new AtomicLong();private static volatile AutoCloudBackupEngine active;private static volatile AtomicBoolean activeCancellation;
 static final class State {final boolean enabled,busy;final String message;final int pending,attention,verified;State(boolean enabled,boolean busy,String message,int pending,int attention,int verified){this.enabled=enabled;this.busy=busy;this.message=message;this.pending=pending;this.attention=attention;this.verified=verified;}}
 static volatile State state=new State(false,false,"Loading automatic backup preference…",0,0,0);
 private static Context app(Context c){return c.getApplicationContext();}
 private static void publish(AutoCloudBackupStore s){AutoCloudBackupStore.Owner o=s.owner();state=new State(o.enabled,active!=null,o.message+(!o.enabled&&active!=null?" · waiting for provider cleanup":""),s.countOwned("PENDING","PREPARING","CREATING","CREATED"),s.countOwned("FAILED","UNCERTAIN"),s.countOwned("VERIFIED"));}
 private static void submit(Context context,Consumer<AutoCloudBackupEngine> work){Context c=app(context);Factory pinned=factory;Records.Factory records=Records.factory;Environments effects=environments;if(pinned==PRODUCTION&&records!=Records.PRODUCTION){state=new State(false,false,"Off · automatic delivery requires the app’s recording database",0,0,0);return;}io.execute(()->{try(AutoCloudBackupStore s=pinned.open(c)){AutoCloudBackupEngine engine=new AutoCloudBackupEngine(s,effects.create(c,records));try{work.accept(engine);}catch(RuntimeException failure){publish(s);State fresh=state;state=new State(fresh.enabled,false,"Automatic backup needs attention: "+safe(failure),fresh.pending,fresh.attention,fresh.verified);return;}publish(s);}catch(Exception failure){State old=state;state=new State(old.enabled,false,"Automatic backup needs attention: "+safe(failure),old.pending,old.attention,old.verified);}});}
 private static String safe(Exception e){String m=e.getMessage();return m==null?"Reopen and retry":m;}
 static void inspect(Context c){submit(c,e->{});}
 static void configure(Context context,boolean on){if(on&&(state.busy||active!=null||offPending.get()))return;if(!on&&!offPending.compareAndSet(false,true))return;invalidate();long expected=generation.get();State old=state;state=new State(old.enabled,true,on?"Checking the selected destination…":"Turning automatic backup off…",old.pending,old.attention,old.verified);if(on){submit(context,e->{try{e.configure(true,()->generation.get()==expected);}catch(Exception failure){if(generation.get()!=expected)return;throw new IllegalStateException(failure.getMessage(),failure);}});return;}Context c=app(context);Factory pinned=factory;Records.Factory records=Records.factory;Environments effects=environments;if(pinned==PRODUCTION&&records!=Records.PRODUCTION){offPending.set(false);state=old;return;}control.execute(()->{try(AutoCloudBackupStore s=pinned.open(c)){new AutoCloudBackupEngine(s,effects.create(c,records)).configure(false,()->true);publish(s);}catch(Exception failure){State previous=state;state=new State(previous.enabled,active!=null,"Off could not be saved. Reopen and retry.",previous.pending,previous.attention,previous.verified);}finally{offPending.set(false);}});}
 static void destinationChanged(Context c){if(factory!=PRODUCTION||CloudBackupSettings.factory!=CloudBackupSettings.PRODUCTION)return;invalidate();submit(c,e->{try{e.reconcile(false);}catch(Exception failure){throw new IllegalStateException(failure);}});}
 static void retry(Context c){submit(c,e->{try{e.retry();}catch(Exception failure){throw new IllegalStateException(failure);}});}
 static void recoverExisting(Context context){Context c=app(context);if(factory!=PRODUCTION||Records.factory!=Records.PRODUCTION||CloudBackupSettings.factory!=CloudBackupSettings.PRODUCTION||environments!=PRODUCTION_ENVIRONMENT||!c.getDatabasePath(AutoCloudBackupStore.DATABASE).isFile())return;io.execute(()->{if(factory!=PRODUCTION||Records.factory!=Records.PRODUCTION||CloudBackupSettings.factory!=CloudBackupSettings.PRODUCTION||environments!=PRODUCTION_ENVIRONMENT)return;try(AutoCloudBackupStore s=PRODUCTION.open(c)){new AutoCloudBackupEngine(s,new AndroidEnvironment(c,Records.PRODUCTION)).reconcile(true);publish(s);}catch(Exception error){State old=state;state=new State(old.enabled,false,"Automatic backup recovery needs attention. Reopen Cloud backup.",old.pending,old.attention,old.verified);}});}
 static void recover(Context c){submit(c,e->{try{e.reconcile(true);}catch(Exception failure){throw new IllegalStateException(failure);}});}
 static void cancel(AtomicBoolean run){run.set(true);AutoCloudBackupEngine e=active;if(e!=null&&activeCancellation==run)e.cancelProvider();}
 static void invalidate(){generation.incrementAndGet();AutoCloudBackupEngine e=active;if(e!=null)e.cancelProvider();}
 /** Called only AFTER a successful runtime end, never from Store.end/migration/manual records. */
 static void ended(Context c,long id,long start,long end,boolean production){if(!production||factory!=PRODUCTION||Records.factory!=Records.PRODUCTION||CloudBackupSettings.factory!=CloudBackupSettings.PRODUCTION||environments!=PRODUCTION_ENVIRONMENT)return;AutoCloudAudio.ended(c,id,start,end,production);Context application=app(c);submit(application,e->{try{AutoCloudBackupStore.Owner o=e.store.owner();if(!o.enabled)return;try(Store s=Records.PRODUCTION.open(application)){if(!valid(s,id,start,end))return;}e.ended(id,start,end);}catch(Exception failure){throw new IllegalStateException("Could not queue saved-night backup",failure);}});}
 static boolean valid(Store s,long id,long start,long end){List<org.json.JSONObject> rows=s.rows("SELECT * FROM sessions WHERE id=?",Long.toString(id));if(rows.size()!=1)return false;org.json.JSONObject r=rows.get(0);return r.optLong("start")==start&&!r.isNull("end")&&r.optLong("end")==end&&AutoCloudBackupPolicy.eligible(id,start,end,r.optInt("interrupted",1)!=0,r.optString("source"),r.optString("origin"));}
 static void run(Context c,String token,AtomicBoolean cancelled,Runnable finished){Context application=app(c);Factory pinned=factory;Records.Factory records=Records.factory;Environments effects=environments;long admission=generation.get();State previous=state;state=new State(previous.enabled,true,"Automatic metadata backup is running…",previous.pending,previous.attention,previous.verified);if(pinned==PRODUCTION&&records!=Records.PRODUCTION){state=previous;finished.run();return;}io.execute(()->{try(AutoCloudBackupStore s=pinned.open(application)){AutoCloudBackupEngine engine=new AutoCloudBackupEngine(s,effects.create(application,records));activeCancellation=cancelled;active=engine;try{engine.store.recover();engine.run(token,()->!cancelled.get()&&generation.get()==admission);}finally{active=null;activeCancellation=null;}publish(s);}catch(Exception failure){State old=state;state=new State(old.enabled,false,"Automatic backup needs attention: "+safe(failure),old.pending,old.attention,old.verified);}finally{finished.run();}});}
 static void drain(long timeout)throws Exception{control.submit(()->{}).get(timeout,TimeUnit.MILLISECONDS);io.submit(()->{}).get(timeout,TimeUnit.MILLISECONDS);}
 static final class AndroidEnvironment implements AutoCloudBackupEngine.Environment {
  final Context c;final Records.Factory records;final SharedPreferences prefs;
  AndroidEnvironment(Context c,Records.Factory records){this.c=c;this.records=records;prefs=CloudBackupSettings.factory.preferences(c);}
  public CloudBackupSettings.Destination destination(){return CloudBackupSettings.destination(prefs);}
  public boolean granted(CloudBackupSettings.Destination d){return !d.tree.isEmpty()&&CloudBackupProvider.granted(c.getContentResolver(),android.net.Uri.parse(d.tree));}
  public void verify(CloudBackupSettings.Destination d)throws Exception{if(!granted(d))throw new SecurityException("Folder access was lost. Choose it again.");new CloudBackupProvider(c,d.tree).label();}
  public boolean valid(AutoCloudBackupStore.Task t){try(Store s=records.open(c)){return AutoCloudBackups.valid(s,t.session,t.start,t.end);}}
  public byte[] snapshot(BooleanSupplier active)throws Exception{return CloudBackupSnapshot.prepare(c,records,active);}
  public CloudBackupCopy.Provider provider(String tree){return new CloudBackupProvider(c,tree);}
  public void history(AutoCloudBackupStore.Task t,CloudBackupCopy.Document d,CloudBackupCopy.Receipt r)throws Exception{CloudBackupSettings.record(prefs,new CloudBackupSettings.Entry(t.tree,d.uri,d.name,System.currentTimeMillis(),r==null?0:r.size,r==null?"":r.sha,r!=null));}
  public long now(){return System.currentTimeMillis();}
  public void schedule(String token,long due){PersistableBundle extras=new PersistableBundle();extras.putString("owner",token);int result=c.getSystemService(JobScheduler.class).schedule(new JobInfo.Builder(JOB,new ComponentName(c,AutoCloudBackupService.class)).setExtras(extras).setPersisted(true).setRequiresBatteryNotLow(true).setMinimumLatency(Math.max(60000,due-now())).build());if(result!=JobScheduler.RESULT_SUCCESS)throw new IllegalStateException("Android deferred job scheduling. Retry automatic backup.");}
  public void cancel(){c.getSystemService(JobScheduler.class).cancel(JOB);}
 }
 private AutoCloudBackups(){}
}
